"""Curated Master Cinema Catalog & Top 100 Greatest Movies of All Time.

Contains multi-source ratings (IMDb, Rotten Tomatoes, Metacritic, Letterboxd),
box office metrics, director metadata, and streaming platforms.
"""

from typing import Dict, List, Any

def calculate_cinescore(imdb: float, rt: int, meta: int, lb: float) -> float:
    """Calculates normalized CineScore (0 - 100) weighted across 4 major critical sources."""
    norm_imdb = (imdb / 10.0) * 100
    norm_rt = float(rt)
    norm_meta = float(meta)
    norm_lb = (lb / 5.0) * 100
    score = (norm_imdb * 0.35) + (norm_rt * 0.30) + (norm_meta * 0.20) + (norm_lb * 0.15)
    return round(score, 1)

