# Generate Master DB with CineScore
MASTER_MOVIES_DB: List[Dict[str, Any]] = []
for idx, m in enumerate(RAW_TOP_100, 1):
    m_copy = dict(m)
    m_copy["id"] = f"tt_top100_{idx:03d}"
    m_copy["rank_top100"] = idx
    m_copy["cinescore"] = calculate_cinescore(m_copy["imdb_rating"], m_copy["rotten_tomatoes_pct"], m_copy["metacritic_score"], m_copy["letterboxd_rating"])
    MASTER_MOVIES_DB.append(m_copy)
